"""Five answerable native-body questions with exact own-panel numbering."""
import argparse,json,html
from .common import *
PAINT={'red':'#d93640','yellow':'#f1c934','black':'#202936','?':'white'}
CASES=[
 dict(residue=27,targets=['NEW-2185-1265','NEW-1221-2081'],title='Two red records versus three black records',question='In each named target photograph, inspect the visible body carrying feature 1. Is its pigment red, or is the bright/tinted patch on a black body? Please answer by photograph ID and its own feature number. If the visible material does not settle it, say uncertain.',consequence='Both red records would need independent resolution before this residue could become unanimous. A black majority is not itself a correction.'),
 dict(residue=92,targets=['NEW-2235-1476'],title='One distinguishable dark body is recorded red',question='In the NEW-2235-1476 target photograph, does feature 1 belong to a red-bodied bead or a black-bodied bead with a bright patch? Use the visible body around the patch and the neighboring colored bodies; feature 1 is a support, not a measured bead center.',consequence='This single red record conflicts with four black records. Its image-based resolution could settle residue 92 without changing a link.'),
 dict(residue=112,targets=['NEW-910-2406'],title='A serious red-versus-black test of exact 208',question='In the NEW-910-2406 target photograph, is feature 1 a genuinely red-bodied bead, or a colored reflection on a black-bodied bead? Compare the same position in the named black and red occurrences below. Please confirm a visible pigment only if you can distinguish the body from the bright patch.',consequence='If genuine red and black bodies at this residue are both confirmed, exact 208 fails on the current associations. That would require investigation, not a majority recoloring or isolated index edit.'),
 dict(residue=157,targets=['E9-2263-1691'],title='A bright patch on a visible dark body',question='In the E9-2263-1691 target photograph, what pigment belongs to the bead body carrying feature 1: red or black? The current record is red; the two intensity procedures disagree or abstain, so no automatic correction was made.',consequence='One red record conflicts with four black records. A body judgment could resolve this position; the other occurrences do not determine its color.'),
 dict(residue=196,targets=['E5-2272-1815','NEW-2156-1135'],title='Yellow, red and black records occupy one pattern position',question='For each of the two named target photographs, inspect its own feature 1. Which pigment belongs to that visible body: yellow, red or black? E5-2272-1815 is recorded yellow; NEW-2156-1135 is recorded red. Do not transfer the feature numbers between photographs.',consequence='Three other records are black. Both colored records remain authoritative working labels until independently resolved. The newly inspected low-contrast candidate near(1009,2826) was not admitted or used as another vote.')]

def run(out):
    out=Path(out);out.mkdir(parents=True,exist_ok=False);g=read(artifact('results/graph.json.gz'));obs={o['id']:o for o in g['observations']};co={r['id']:r['ab'] for r in g['coordinates']};a=read(artifact('analysis/analysis.json.gz'));summary={k:v for k,v in read(artifact('results/summary.json')).items() if k!='seconds'};p=a['cohorts']['R338_expanded'];measurement={r['id']:r for r in read(artifact('measurement/pigment.json.gz'))['records']};photo=Image.fromarray(photograph());panels={};crops=[];groups=[]
    def panel(oid,role,key):
        x,y=obs[oid]['xy'];box=[int(x)-100,int(y)-85,int(x)+101,int(y)+86];local=[o for o in co if box[0]+5<obs[o]['xy'][0]<box[2]-5 and box[1]+5<obs[o]['xy'][1]<box[3]-5];local.sort(key=lambda o:(o!=oid,obs[o]['xy'][1],obs[o]['xy'][0]));numbers={o:j+1 for j,o in enumerate(local)};keys=[dict(number=numbers[o],id=o,xy=obs[o]['xy'],ab=co[o],color=obs[o]['color'],indexA=(7*co[o][0]+6*co[o][1])%2704,residue=(7*co[o][0]+6*co[o][1])%208) for o in local];file=key+'-native.png';photo.crop(box).save(out/file);crops.append(dict(file=file,bbox=box));bodybox=[int(x)-25,int(y)-25,int(x)+26,int(y)+26];bodyfile=key+'-body.png';photo.crop(bodybox).save(out/bodyfile);crops.append(dict(file=bodyfile,bbox=bodybox));edges=[e for e in g['edges'] if e['source'] in numbers and e['target'] in numbers];k=(7*co[oid][0]+6*co[oid][1])%2704;panels[key]=dict(id=oid,role=role,key=keys,bbox=box,image=file,body=bodyfile,edges=edges,indexA=k,residue=k%208,occurrence=k//208,measurement={q:measurement.get(oid,{}).get(q) for q in ['black_first','broad_decision','compact_decision']});return key
    for spec in CASES:
        slot=p['entries'][spec['residue']];others=[o for o in slot['ids'] if o not in spec['targets']];others.sort(key=lambda o:(obs[o]['color']=='red',-(7*co[o][0]+6*co[o][1])%2704,o));selected=spec['targets']+others[:max(3,4-len(spec['targets']))];ps=[]
        for j,o in enumerate(selected):ps.append(panel(o,'target for judgment' if o in spec['targets'] else 'same 208 residue; recorded comparison',f'r{spec["residue"]:03d}-{j+1}'))
        groups.append(dict(spec,counts=slot['counts'],panels=ps,all_ids=slot['ids']))
    done=panel('R332-B-0098-0092','completed association; no question','completed-known-body')
    def render_panel(name):
        r=panels[name];box=r['bbox'];w,h=box[2]-box[0],box[3]-box[1];num={v['id']:v['number'] for v in r['key']};native=f'<svg viewBox="0 0 {w} {h}" class="native"><image href="{r["image"]}" width="{w}" height="{h}"/>'
        for e in r['edges']:
            pp=np.array(obs[e['source']]['xy'])-box[:2];qq=np.array(obs[e['target']]['xy'])-box[:2];color={'F0':'#18c8dd','F1':'#53c889','difference':'#dfb34e'}[e['family']];native+=f'<path class="photo-link" d="M{pp[0]} {pp[1]}L{qq[0]} {qq[1]}" stroke="{color}" stroke-width=".65" style="display:none"/>'
        for k in r['key']:
            xx,yy=np.array(k['xy'])-box[:2];native+=f'<g class="photo-number"><circle cx="{xx}" cy="{yy}" r="1.5" fill="none" stroke="white" stroke-width=".5"/><text x="{xx+3}" y="{yy-3}" fill="white" stroke="#172331" stroke-width=".4" paint-order="stroke" font-size="6">{k["number"]}</text></g>'
        native+='</svg>';anchor=np.array(co[r['id']]);H=np.array(g['H']);localco={o:(np.array(co[o])-np.rint((np.array(co[o])-anchor)@H/(H@H)).astype(int)*H) for o in num};aa=np.array([localco[o] for o in num]);xx=aa.sum(1)*18;yy=(aa[:,0]-aa[:,1])*23;pos={o:(float(x-xx.min()+18),float(y-yy.min()+18)) for o,x,y in zip(num,xx,yy)};width=float(xx.max()-xx.min()+42);height=float(yy.max()-yy.min()+42);diag=f'<svg viewBox="0 0 {width} {height}" class="diagram"><rect width="100%" height="100%" fill="#f0f5f9"/>'
        for e in r['edges']:
            pp,qq=pos[e['source']],pos[e['target']];color={'F0':'#18a7c2','F1':'#3b9b6b','difference':'#c18a22'}[e['family']];diag+=f'<path d="M{pp[0]} {pp[1]}L{qq[0]} {qq[1]}" stroke="{color}" stroke-width="1.2"/>'
        for k in r['key']:
            x,y=pos[k['id']];diag+=f'<circle cx="{x}" cy="{y}" r="{8 if k["number"]==1 else 6}" fill="{PAINT[k["color"]]}" stroke="white" stroke-width="1"/><text x="{x+7}" y="{y-5}" font-size="9" fill="#1a2634">{k["number"]}</text>'
        diag+='</svg>';keys='<table><thead><tr><th>Local #</th><th>Stable ID</th><th>Recorded color</th><th>Native xy</th><th>ab</th></tr></thead><tbody>'+''.join(f'<tr><td>{k["number"]}</td><td>{k["id"]}</td><td>{k["color"]}</td><td>{k["xy"][0]:.3f},{k["xy"][1]:.3f}</td><td>{k["ab"]}</td></tr>' for k in r['key'])+'</tbody></table>'
        return f'<section class="panel" data-panel="{name}"><h3>Photograph {r["id"]}</h3><p>{r["role"]}. Feature 1 is {r["id"]}, recorded {obs[r["id"]]["color"]}; A index {r["indexA"]}, occurrence {r["occurrence"]}, residue {r["residue"]}. These indices are conditional.</p><div class="pair"><figure><div class="stage">{native}</div><figcaption>Original native pixels; own local numbers.</figcaption></figure><figure>{diag}<figcaption>Current colors and actual working adjacency, same numbers.</figcaption></figure></div><details><summary>Feature 1 body crop and exact local key ({len(r["key"])} observations)</summary><img class="body" src="{r["body"]}" alt="Unaltered close crop of {r["id"]}"><div class="scroll">{keys}</div></details><p><a href="{r["image"]}">Open unannotated native photograph</a>. Broad/compact intensity decisions: {r["measurement"]["broad_decision"]}/{r["measurement"]["compact_decision"]}; neither establishes body identity or overrules maker colors.</p></section>'
    cards=[]
    for i,c in enumerate(groups):
        targetnames=', '.join(c['targets']);cards.append(f'<article class="case" id="case-{i}" {"" if i==0 else "hidden"}><p class="tag">Question {i+1} of {len(groups)} · proposed 208 position {c["residue"]}</p><h2>{c["title"]}</h2><p>Current recorded colors at this position: {html.escape(str(c["counts"]))}. Targets: {targetnames}.</p><div class="question"><p><b>Question:</b> {c["question"]}</p><p><b>Why it matters:</b> {c["consequence"]}</p></div>'+''.join(render_panel(n) for n in c['panels'])+'</article>')
    slots=[]
